222				line := strings.Repeat(".", tc.width)
223				got, ok := Splice(line, tc.box, tc.x, tc.width)
224				if ok {
225					t.Errorf("ok = true, want false (got %q)", got)
226				}
227				assertNoOrphan(t, got)
228			})
