232	func TestSpliceEmptyBox(t *testing.T) {
233		line := strings.Repeat(".", 40)
234		got, ok := Splice(line, "", 5, 40)
235		if !ok {
236			t.Fatal("empty box must not fail")
237		}
238		assertWidth(t, got, 40)
239		if ansi.Strip(got) != line {
240			t.Errorf("empty box altered the line: %q", ansi.Strip(got))
241		}
242	}
243	
244	func TestComposeBasics(t *testing.T) {
245		for _, width := range widths {
246			base := make([]string, 10)
247			for i := range base {
248				base[i] = baseSGR + strings.Repeat("a", width) + reset
249			}
250			box := []string{"+----+", "| hi |", "+----+"}
251	
252			got := Compose(base, box, 7, 3, width)
253	
254			if len(got) != len(base) {
255				t.Fatalf("width %d: %d lines, want %d", width, len(got), len(base))
256			}
257			for i, l := range got {
258				assertWidth(t, l, width)
259				assertNoOrphan(t, l)
260				plain := ansi.Strip(l)
261				if i >= 3 && i < 6 {
262					if got, want := plain[7:13], box[i-3]; got != want {
263						t.Errorf("row %d: box = %q, want %q", i, got, want)
264					}
265				} else if plain != strings.Repeat("a", width) {
266					t.Errorf("row %d outside the box changed: %q", i, plain)
267				}
268			}
269		}
270	}
271	
272	func TestComposeDoesNotMutateBase(t *testing.T) {
273		base := []string{"aaaa", "bbbb"}
274		orig := append([]string(nil), base...)
275		_ = Compose(base, []string{"X"}, 1, 0, 4)
276		if !reflect.DeepEqual(base, orig) {
277			t.Errorf("base mutated: %q", base)
278		}
279	}
280	
281	func TestComposePadsShortBaseLines(t *testing.T) {
282		got := Compose([]string{"", "ab"}, []string{"BOX", "BOX"}, 2, 0, 40)
283		if len(got) != 2 {
284			t.Fatalf("len = %d", len(got))
285		}
286		for _, l := range got {
287			assertWidth(t, l, 40)
288			if ansi.Strip(l)[2:5] != "BOX" {
289				t.Errorf("box missing: %q", ansi.Strip(l))
290			}
291		}
292	}
293	
294	func TestComposeOutOfBounds(t *testing.T) {
295		base := []string{strings.Repeat("a", 40), strings.Repeat("b", 40), strings.Repeat("c", 40)}
296		box := []string{"111", "222", "333"}
297	
298		tests := []struct {
299			name      string
300			y         int
301			spliced   []int // rows expected to carry box text
302			unchanged bool
303		}{
304			{"y beyond base", 10, nil, true},
305			{"y equals len", 3, nil, true},
306			{"box overruns the bottom", 2, []int{2}, false},
307			{"y negative drops the top rows", -1, []int{0, 1}, false},
308			{"y far negative", -10, nil, true},
309		}
310		for _, tc := range tests {
311			t.Run(tc.name, func(t *testing.T) {
312				got := Compose(base, box, 5, tc.y, 40)
313				if len(got) != len(base) {
314					t.Fatalf("%d lines, want %d", len(got), len(base))
315				}
316				for i, l := range got {
317					assertWidth(t, l, 40)
318					assertNoOrphan(t, l)
319					has := strings.Contains(ansi.Strip(l), "111") ||
320						strings.Contains(ansi.Strip(l), "222") ||
321						strings.Contains(ansi.Strip(l), "333")
322					want := false
323					for _, r := range tc.spliced {
324						want = want || r == i
325					}
326					if has != want {
327						t.Errorf("row %d: box present = %v, want %v (%q)", i, has, want, ansi.Strip(l))
328					}
329				}
330				if tc.unchanged {
331					for i := range base {
332						if ansi.Strip(got[i]) != base[i] {
333							t.Errorf("row %d changed: %q", i, ansi.Strip(got[i]))
334						}
335					}
336				}
337			})
338		}
339	}
340	
341	func TestComposeUnchangedInputs(t *testing.T) {
342		base := []string{baseSGR + strings.Repeat("a", 40) + reset, "second"}
343		tests := []struct {
344			name  string
345			box   []string
346			x, y  int
347			width int
348		}{
349			{"empty box", nil, 2, 0, 40},
350			{"box of empty strings", []string{""}, 2, 0, 40},
351			{"negative x", []string{"BOX"}, -1, 0, 40},
352			{"zero width", []string{"BOX"}, 2, 0, 0},
353			{"negative width", []string{"BOX"}, 2, 0, -5},
354			{"empty base", []string{"BOX"}, 2, 0, 40},
355		}
356		for _, tc := range tests {
357			t.Run(tc.name, func(t *testing.T) {
358				in := base
359				if tc.name == "empty base" {
360					in = nil
361				}
362				got := Compose(in, tc.box, tc.x, tc.y, tc.width)
363				if len(got) != len(in) {
364					t.Fatalf("%d lines, want %d", len(got), len(in))
365				}
366				if tc.name == "empty box" || tc.name == "negative x" ||
367					tc.name == "zero width" || tc.name == "negative width" {
368					if !reflect.DeepEqual(got, in) {
369						t.Errorf("base not returned unchanged: %q", got)
370					}
371				}
372			})
373		}
374	}
375	
376	func TestComposeFallbackOnlyForTheFailingRow(t *testing.T) {
377		const width = 40
378		base := []string{strings.Repeat("a", width), strings.Repeat("b", width), strings.Repeat("c", width)}
379		// Row 1 is wider than the room right of x=30; rows 0 and 2 fit.
380		box := []string{"ok", strings.Repeat("#", 20), "ok"}
381	
382		got := Compose(base, box, 30, 0, width)
383		if len(got) != 3 {
384			t.Fatalf("len = %d", len(got))
385		}
386		for i, l := range got {
387			assertWidth(t, l, width)
388			assertNoOrphan(t, l)
389			if i != 1 && ansi.Strip(l)[30:32] != "ok" {
390				t.Errorf("row %d should be spliced: %q", i, ansi.Strip(l))
391			}
392		}
393		if !strings.Contains(ansi.Strip(got[1]), "#") {
394			t.Errorf("fallback row lost the box: %q", ansi.Strip(got[1]))
395		}
396	}
397	
398	func TestComposeBoxWiderThanBase(t *testing.T) {
399		for _, width := range widths {
400			base := []string{strings.Repeat("a", width), strings.Repeat("b", width)}
401			box := []string{strings.Repeat("#", width+30), "x"}
402			got := Compose(base, box, 0, 0, width)
403			if len(got) != 2 {
404				t.Fatalf("len = %d", len(got))
405			}
406			for _, l := range got {
407				assertWidth(t, l, width)
408				assertNoOrphan(t, l)
409			}
410		}
411	}
412	
413	func TestComposeStyledWideRunes(t *testing.T) {
414		const width = 40
415		line := baseSGR + strings.Repeat("世", width/2) + reset
416		base := []string{line, line, line}
417		for x := 0; x < 8; x++ {
418			got := Compose(base, []string{"ABC", "DEF"}, x, 1, width)
419			for i, l := range got {
420				assertWidth(t, l, width)
421				assertNoOrphan(t, l)
422				if i == 0 && ansi.Strip(l) != ansi.Strip(line) {
423					t.Errorf("x=%d: untouched row changed", x)
424				}
425			}
426		}
427	}
